<script setup lang="ts">
import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {api} from '../api';import {ElMessage} from 'element-plus';
const router=useRouter(), register=ref(false), busy=ref(false), form=reactive({username:'',password:''});
async function submit(){if(!form.username||!form.password){ElMessage.warning('请填写用户名和密码');return}busy.value=true;try{const r:any=await api.post('/auth/'+(register.value?'register':'login'),form);localStorage.setItem('token',r.data.token);await router.push('/')}finally{busy.value=false}}
</script><template><main class="login-wrap"><section class="login-card"><div class="mark">✳</div><h1>校园报修，简单一点</h1><p class="muted">AI Repair Hub · 宿舍维修服务平台</p><el-form @submit.prevent="submit" label-position="top"><el-form-item label="用户名"><el-input v-model="form.username" placeholder="3–32 位字母、数字或下划线" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password placeholder="至少 8 位" @keyup.enter="submit" /></el-form-item><el-button type="primary" class="wide" :loading="busy" @click="submit">{{ register?'注册学生账号':'登录' }}</el-button></el-form><div class="switch" @click="register=!register">{{ register?'已有账号？去登录':'还没有账号？注册学生账号' }}</div></section></main></template>
